INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(38911, 'Proverbs 26:11', 'Proverbs', 26, 11, 'لکه څنګه چې سپی خپلې کانګې بېرته څټي همداسې کم‌عقل خپل جهالت بیا تکراروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_11.mp3', '', 1761754199, 1761754199),
(38912, 'Proverbs 26:12', 'Proverbs', 26, 12, 'څوک چې خپل ځان د حکمت خاوند ګڼي نو هغه د یو کم‌عقل نه هم ډېر بد دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_12.mp3', '', 1761754199, 1761754199),
(38913, 'Proverbs 26:13', 'Proverbs', 26, 13, 'لټ سړی له کور څخه نه وځي او وایي: «په کوڅه کې زمری دی! او په چوکونو کې غړمبېدونکي زمري ګرځي راګرځي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_13.mp3', '', 1761754199, 1761754199),
(38914, 'Proverbs 26:14', 'Proverbs', 26, 14, 'لکه څنګه چې دروازه په خپلو قبضو باندې تاویږي راتاویږي همداسې لټ سړی په خپل کټ کې اوړي را‌اوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_14.mp3', '', 1761754199, 1761754199),
(38915, 'Proverbs 26:15', 'Proverbs', 26, 15, 'لټ انسان کاسې ته لاس غزولی شي خو د لټۍ نه یې بېرته خولې ته وړلی نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_15.mp3', '', 1761754199, 1761754199),
(38916, 'Proverbs 26:16', 'Proverbs', 26, 16, 'لټ انسان خپل ځان د حکمت خاوند ګڼي د اووه هوښیارانو نه چې په حکمت ځواب ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_16.mp3', '', 1761754199, 1761754199),
(38917, 'Proverbs 26:17', 'Proverbs', 26, 17, 'څوک چې په غوسه د بل په شخړه کې لاس وهنه کوي لکه څوک چې کوڅه‌ډب سپی له غوږونو نه راونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_17.mp3', '', 1761754199, 1761754199),
(38918, 'Proverbs 26:18', 'Proverbs', 26, 18, 'لکه څنګه چې یو لېونی د اور سکروټې او وژونکي غشي وروي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_18.mp3', '', 1761754199, 1761754199),
(38919, 'Proverbs 26:19', 'Proverbs', 26, 19, 'د هغه چا په شان دی څوک چې بل غولوي او بیا وایي چې ما ټوکې کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_19.mp3', '', 1761754199, 1761754199),
(38920, 'Proverbs 26:20', 'Proverbs', 26, 20, 'له لرګیو او پوکي پرته اور مړ کیږي او د غیبت پرته جنګ ختمیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_20.mp3', '', 1761754199, 1761754199),
(38921, 'Proverbs 26:21', 'Proverbs', 26, 21, 'لکه څنګه چې لرګي اور اخلي او سکاره په سکروټو بدلیږي همداسې د جنګ اور له جګړه‌مار سړي نه پورته کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_21.mp3', '', 1761754199, 1761754199),
(38922, 'Proverbs 26:22', 'Proverbs', 26, 22, 'د غیبت کوونکي خبرې د خوندور خوراک په شان دي چې د انسان له ستوني تېریږي او د ګېډې تل ته ښکته کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_22.mp3', '', 1761754199, 1761754199),
(38923, 'Proverbs 26:23', 'Proverbs', 26, 23, 'خوږې خبرې د زړه شرارت پټوي لکه په خاورین لوښي چې رنګ پورې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_23.mp3', '', 1761754199, 1761754199),
(38924, 'Proverbs 26:24', 'Proverbs', 26, 24, 'کینه ناک انسان په خوږو خبرو خپله کرکه پټوي خو د زړه په تل کې یې ټګي ساتلې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_24.mp3', '', 1761754199, 1761754199),
(38925, 'Proverbs 26:25', 'Proverbs', 26, 25, 'کله چې هغه خوږې خبرې کوي نو باور پرې مه کوه ځکه زړه یې د اووه بدیو نه ډک دی چې د کرکې وړ دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_25.mp3', '', 1761754199, 1761754199),
(38926, 'Proverbs 26:26', 'Proverbs', 26, 26, 'که د هغه کرکه په دروغو د پردې لاندې پټه وي خو شرارت به یې ټولو خلکو ته بیاهم ښکاره شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_26.mp3', '', 1761754199, 1761754199),
(38927, 'Proverbs 26:27', 'Proverbs', 26, 27, 'څوک چې بل ته کنده کیندي نو په خپله به په کې راوغورځیږي او څوک چې د بل په طرف تیږه ورغړوي نو په خپله به پرې راورغړیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_27.mp3', '', 1761754199, 1761754199),
(38928, 'Proverbs 26:28', 'Proverbs', 26, 28, 'دروغجنه ژبه او کرکه د سړي زړه ټوټې ټوټې کوي او د غوړه‌مالۍ خبرې تباهي راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_28.mp3', '', 1761754199, 1761754199),
(38929, 'Proverbs 11:1', 'Proverbs', 11, 1, 'څښتن د تلې له غلط کارولو نه کرکه کوي خو په پوره کاڼي تول تل خوښوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_1.mp3', '', 1761754199, 1761754199),
(38930, 'Proverbs 11:2', 'Proverbs', 11, 2, 'کله چې غرور راشي نو رسوایي هم راځي خو د عاجزۍ سره حکمت راځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_2.mp3', '', 1761754199, 1761754199),
(38931, 'Proverbs 11:3', 'Proverbs', 11, 3, 'د صادقانو پاک زړه د هغوی لارښوونه کوي خو د خاینانو ګمراهي هغوی تباه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_3.mp3', '', 1761754199, 1761754199),
(38932, 'Proverbs 11:4', 'Proverbs', 11, 4, 'د عدالت په ورځ دولت ګټه نه لري خو صداقت انسان له مرګ نه ژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_4.mp3', '', 1761754199, 1761754199),
(38933, 'Proverbs 11:5', 'Proverbs', 11, 5, 'د پاک انسان صداقت د هغه لار سموي خو د بدکاره انسان بدي هغه راغورځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_5.mp3', '', 1761754199, 1761754199),
(38934, 'Proverbs 11:6', 'Proverbs', 11, 6, 'د رښتینو خلکو صداقت هغوی ژغوري خو د خاینانو غوښتنې هغوی په دام کې نښلوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_6.mp3', '', 1761754199, 1761754199),
(38935, 'Proverbs 11:7', 'Proverbs', 11, 7, 'کله چې یو بدکاره مري هیله یې تباه کیږي نو زر او زور او ټول ارمانونه یې هم تباه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_7.mp3', '', 1761754199, 1761754199),
(38936, 'Proverbs 11:8', 'Proverbs', 11, 8, 'نېک انسان له سختۍ نه ژغورل کیږي او په ځای یې بدکاره انسان د تکلیف په لور روانیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_8.mp3', '', 1761754199, 1761754199),
(38937, 'Proverbs 11:9', 'Proverbs', 11, 9, 'بې‌ایمانه انسان په خپلو خبرو نور تباه کوي خو نېکان د خپل علم له امله ژغورل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_9.mp3', '', 1761754199, 1761754199),
(38938, 'Proverbs 11:10', 'Proverbs', 11, 10, 'نېکان چې بریالي کیږي ټول ښار پرې خوشحالیږي او بدکاران چې تباه کیږي د خوشحالۍ چیغې وهل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_10.mp3', '', 1761754199, 1761754199),
(38939, 'Proverbs 11:11', 'Proverbs', 11, 11, 'ښار د رښتینو خلکو په برکت ودانیږي خو د بدکارانو د خولې په خبرو ورانیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_11.mp3', '', 1761754199, 1761754199),
(38940, 'Proverbs 11:12', 'Proverbs', 11, 12, 'څوک چې بل ته په سپکه سترګه ګوري ناپوهه دی خو د پوهې خاوند خپله خوله پټه ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_12.mp3', '', 1761754199, 1761754199),
(38941, 'Proverbs 11:13', 'Proverbs', 11, 13, 'غیبت کوونکی د نورو راز ښکاره کوي خو باوري انسان د بل په راز پرده اچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_13.mp3', '', 1761754199, 1761754199),
(38942, 'Proverbs 11:14', 'Proverbs', 11, 14, 'کله چې ښې مشورې نه وي نو ولس له پښو غورځیږي خو که مشوره ورکوونکي ډېر وي د بریالیتوب سبب ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_14.mp3', '', 1761754199, 1761754199),
(38943, 'Proverbs 11:15', 'Proverbs', 11, 15, 'په قرض کې د بل چا ضمانت کوونکي به زیان ومومي خو په قرض کې له لاس ورکولو نه ډډه کوونکی به ډاډه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_15.mp3', '', 1761754199, 1761754199),
(38944, 'Proverbs 11:16', 'Proverbs', 11, 16, 'مهربانه ښځه تل عزت ګټي خو ظالمان یوازې دولت ګټي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_16.mp3', '', 1761754199, 1761754199),
(38945, 'Proverbs 11:17', 'Proverbs', 11, 17, 'مهربان انسان ځان ته ګټه رسوي خو بې‌رحمه انسان ځان ته زیان رسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_17.mp3', '', 1761754199, 1761754199),
(38946, 'Proverbs 11:18', 'Proverbs', 11, 18, 'د بدکاره سړي ګټه بې‌برکته ده خو د نېکۍ کرونکی حقیقي حاصل رېبي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_18.mp3', '', 1761754199, 1761754199),
(38947, 'Proverbs 11:19', 'Proverbs', 11, 19, 'څوک چې په صداقت ولاړ وي نېکمرغه ژوند لري شرارت پېښوونکی په خپل مرګ پسې ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_19.mp3', '', 1761754199, 1761754199),
(38948, 'Proverbs 11:20', 'Proverbs', 11, 20, 'څښتن د کږو لارو له خاوندانو نه کرکه کوي خو د پاک زړه خاوندان خوښوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_20.mp3', '', 1761754199, 1761754199),
(38949, 'Proverbs 11:21', 'Proverbs', 11, 21, 'باور ولره چې بدکاران به بې‌سزا پاتې نه شي خو د نېکانو اولادونه به خلاصون ومومي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_21.mp3', '', 1761754199, 1761754199),
(38950, 'Proverbs 11:22', 'Proverbs', 11, 22, 'د بې‌تمیزه او بې‌حیا ښځې ښکلا داسې ده لکه د خوګ په پوزه کې چې د سرو زرو پېزوان وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_22.mp3', '', 1761754199, 1761754199),
(38951, 'Proverbs 11:23', 'Proverbs', 11, 23, 'د نېکانو هیلې په برکت تمامیږي خو د بدکارانو امیدونه د غضب سبب ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_23.mp3', '', 1761754199, 1761754199),
(38952, 'Proverbs 11:24', 'Proverbs', 11, 24, 'څوک چې سخاوت کوي نور به هم شتمن شي خو څوک چې سختي کوي نور به هم نېستمن شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_24.mp3', '', 1761754199, 1761754199),
(38953, 'Proverbs 11:25', 'Proverbs', 11, 25, 'یو سخي سړی به تل اباد شي څوک چې د نورو تنده ماتوي خپله تنده به یې هم ماته شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_25.mp3', '', 1761754199, 1761754199),
(38954, 'Proverbs 11:26', 'Proverbs', 11, 26, 'د ګرانۍ په مقصد غله ساتونکي باندې لعنت ویل کیږي خو په خرڅوونکي باندې تل برکت ویل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_26.mp3', '', 1761754199, 1761754199),
(38955, 'Proverbs 11:27', 'Proverbs', 11, 27, 'څوک چې د ښو په لټه کې وي نو د نورو په رضا پسې ګرځي خو څوک چې په شرارت پسې ګرځي نو له مصیبت سره مخامخ کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_27.mp3', '', 1761754199, 1761754199),
(38956, 'Proverbs 11:28', 'Proverbs', 11, 28, 'څوک چې په خپلې شتمنۍ تکیه کوي نو راغورځیږي خو نېکان د شنو پاڼو په شان تازه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_28.mp3', '', 1761754199, 1761754199),
(38957, 'Proverbs 11:29', 'Proverbs', 11, 29, 'خپلې کورنۍ ته مصیبت رسوونکی په باد پسې منډې وهي او جاهل سړی تل د حکمت د خاوند غلام وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_29.mp3', '', 1761754199, 1761754199),
(38958, 'Proverbs 11:30', 'Proverbs', 11, 30, 'د نېک انسان د کار ثمره د ژوندانه ونه ده او د حکمت خاوند د خلکو زړونه لاسته راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_30.mp3', '', 1761754199, 1761754199),
(38959, 'Proverbs 11:31', 'Proverbs', 11, 31, 'که نېکانو ته په دې دنیا کې انعام ورکول کیږي نو د بدکارانو او ګناهکارانو به څه حال وي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs11_verse_31.mp3', '', 1761754199, 1761754199),
(38960, 'Psalms 25:1', 'Psalms', 25, 1, 'څښتنه ستا درګاه ته زه دعا کومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_1.mp3', '', 1761754199, 1761754199),
(38961, 'Psalms 25:2', 'Psalms', 25, 2, 'زما خدایه، توکل دی زما په تا مه مې پرېږده چې شرمنده شم مه پرېږده چې دښمنان مې شي خوشحال راباندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_2.mp3', '', 1761754199, 1761754199),
(38962, 'Psalms 25:3', 'Psalms', 25, 3, 'چې په تا کوي توکل هغه به نه شي شرمنده بې‌سببه چې خیانت کړي شي هغوی به شرمنده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_3.mp3', '', 1761754199, 1761754199),
(38963, 'Psalms 25:4', 'Psalms', 25, 4, 'ای څښتنه، خپلې لارې دې راوښایه ته ماته طریقې د ژوند رازده کړه خپلې ماته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_4.mp3', '', 1761754199, 1761754199),
(38964, 'Psalms 25:5', 'Psalms', 25, 5, 'حقیقي لاره راوښایه ما پوه کړه ځکه ته زما ژغورونکی خدای یې تل په تا باندې توکل کړم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_5.mp3', '', 1761754199, 1761754199),
(38965, 'Psalms 25:6', 'Psalms', 25, 6, 'در په یاد کړه ای څښتنه هغه خپل رحم او تلپاتې مینه چې دې کوله له ازله ځینې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_6.mp3', '', 1761754199, 1761754199),
(38966, 'Psalms 25:7', 'Psalms', 25, 7, 'ګناهونه او سرکښۍ د ځوانۍ مې کړه ته هېرې در په یاد مې کړه څښتنه په تلپاتې مینې خپلې مهربان یې ای څښتنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_7.mp3', '', 1761754199, 1761754199),
(38967, 'Psalms 25:8', 'Psalms', 25, 8, 'څښتن نېک دی او صادق دی ګناهکارو ته ورښایي سمه لاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_8.mp3', '', 1761754199, 1761754199),
(38968, 'Psalms 25:9', 'Psalms', 25, 9, 'عاجزانو ته ورښایي نېغه لاره طریقه خپله وروښایي هغوی ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_9.mp3', '', 1761754199, 1761754199),
(38969, 'Psalms 25:10', 'Psalms', 25, 10, 'هغو خلکو ته به وکړي لارښوونه په مینه او وفا چې ولاړ د ده په لوظ وي او مني د ده حکمونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_10.mp3', '', 1761754199, 1761754199),
(38970, 'Psalms 25:11', 'Psalms', 25, 11, 'د خپل نوم په خاطر دې ای څښتنه ګناهونه زما معاف کړه ځکه زیات دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_11.mp3', '', 1761754199, 1761754199),
(38971, 'Psalms 25:12', 'Psalms', 25, 12, 'هغه څوک چې کوي وېره له څښتنه هغه وبه ښایي هغه ته سمه لاره چې پرې لاړ شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_12.mp3', '', 1761754199, 1761754199),
(38972, 'Psalms 25:13', 'Psalms', 25, 13, 'دی همېش به وي سوکاله اولاده به یې د ځمکې وارثان شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_13.mp3', '', 1761754199, 1761754199),
(38973, 'Psalms 25:14', 'Psalms', 25, 14, 'دی څښتن ملګری د هغو خلکو څوک چې کوي وېره د هغه ځینې دی به هغوی سره خپل لوظ کړي تایید', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_14.mp3', '', 1761754199, 1761754199),
(38974, 'Psalms 25:15', 'Psalms', 25, 15, 'سترګې په لاره یمه همېش څښتن ته ځکه هغه مې خلاصوي د دښمن له دامه څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_15.mp3', '', 1761754199, 1761754199),
(38975, 'Psalms 25:16', 'Psalms', 25, 16, 'زما خواته نظر وکړه ای څښتنه رحم وکړه په ما ځکه چې زه یمه تنها او هم مظلوم یمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_16.mp3', '', 1761754199, 1761754199),
(38976, 'Psalms 25:17', 'Psalms', 25, 17, 'د زړه غمونه مې زیات شوي دي ټولو سختیو نه نجات راکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_17.mp3', '', 1761754199, 1761754199),
(38977, 'Psalms 25:18', 'Psalms', 25, 18, 'زما غمونو، تکلیفونو ته نظر وکړه ته او ګناهونه راته وبخښه ټول', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_18.mp3', '', 1761754199, 1761754199),
(38978, 'Psalms 25:19', 'Psalms', 25, 19, 'ګوره څومره زیات دي دښمنان زما ګوره څومره سخت کوي نفرت له ما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_19.mp3', '', 1761754199, 1761754199),
(38979, 'Psalms 25:20', 'Psalms', 25, 20, 'ته مې وساته خلاصون راکړه ته ماته مه پرېږده چې شرمنده شم له همدې وجې پناه راوړمه تاته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_20.mp3', '', 1761754199, 1761754199),
(38980, 'Psalms 25:21', 'Psalms', 25, 21, 'کړي نېکي او صداقت دې زما ساتنه ځکه چې زه کوم توکل په تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_21.mp3', '', 1761754199, 1761754199),
(38981, 'Psalms 25:22', 'Psalms', 25, 22, 'ته کړه خلاص ای خدایه اسراییل له خپلو ټولو تکلیفونو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms25_verse_22.mp3', '', 1761754199, 1761754199),
(38982, 'Psalms 12:1', 'Psalms', 12, 1, 'مرسته وکړه ای څښتنه! دیندار خلک پاتې نه شول وفادار انسانان ورک شول له دنیا نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms12_verse_1.mp3', '', 1761754199, 1761754199),
(38983, 'Psalms 12:2', 'Psalms', 12, 2, 'دروغ وایي یو بل ته هغوی ټول هغوی یو بل غولوي په چاپلوسۍ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms12_verse_2.mp3', '', 1761754199, 1761754199),
(38984, 'Psalms 12:3', 'Psalms', 12, 3, 'غوړه‌مالې ژبې غوڅې کړه څښتنه! بندې هم لاپوکې خولې کړه چې وایي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms12_verse_3.mp3', '', 1761754199, 1761754199),
(38985, 'Psalms 12:4', 'Psalms', 12, 4, '«مونږ په خپلو ژبو شو ګټلی هرڅه مونږ ویلی شو هرڅه چې مونږ یې غواړو هېڅوک نه شي کړای زمونږه مخنیوی»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms12_verse_4.mp3', '', 1761754199, 1761754199),
(38986, 'Psalms 12:5', 'Psalms', 12, 5, '«خو به زه راپاڅېږمه اوس» څښتن وایي «دا په دې چې په غریبانو ظلم کیږي محتاجان کوي زګېروي له خپله درده ورته ور به کړم امنیت چې په ارمان یې دي»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms12_verse_5.mp3', '', 1761754199, 1761754199),
(38987, 'Psalms 12:6', 'Psalms', 12, 6, 'د څښتن ټولې وعدې داسې سوچه دي لکه اووه ځله چې سپین زر په داشونو کې سوچه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms12_verse_6.mp3', '', 1761754199, 1761754199),
(38988, 'Jeremiah 6:1', 'Jeremiah', 6, 1, 'اے د بنيامين خلقو، د خپل ځان د بچ کېدو دپاره منډه کړئ او د يروشلم نه وتښتئ. په تقوع کښې بيګل وغږوئ او په بيت‌هکرم کښې د خطرې اعلان وکړئ. ځکه چې د شمال طرف نه لوئ افت او بربادى راروانه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_1.mp3', '', 1761754199, 1761754199),
(38989, 'Jeremiah 6:2', 'Jeremiah', 6, 2, 'زما د صيون ښکلې او نازکې لورې تۀ زما خوښه يې خو زۀ به دې تباه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_2.mp3', '', 1761754199, 1761754199),
(38990, 'Jeremiah 6:3', 'Jeremiah', 6, 3, 'تا به دشمن داسې محاصره کړى لکه څنګه چې شپانو د ښار نه ګېرچاپېره خېمې لګولې وى. هر يو به خپل فوجى ته د تباه کولو ځائ ورښائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_3.mp3', '', 1761754199, 1761754199),
(38991, 'Jeremiah 6:4', 'Jeremiah', 6, 4, 'دوئ به چغې وهى، ”راشئ او د جنګ دپاره تيار شئ. راځئ چې مونږ د غرمې په وخت حمله وکړُو. خو افسوس چې اوس ډېر ناوخته شو، د ورځ رڼا په ختمېدو شوه، او د ماښام تيارې راخورې شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_4.mp3', '', 1761754199, 1761754199),
(38992, 'Jeremiah 6:5', 'Jeremiah', 6, 5, 'راځئ چې د شپې په تيارۀ کښې حمله وکړُو او ټول محلونه يې تباه کړُو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_5.mp3', '', 1761754199, 1761754199),
(38993, 'Jeremiah 6:6', 'Jeremiah', 6, 6, 'مالِک ربُ الافواج خُدائ فرمائى چې، ”ونې يې ووهئ، او د خاورو د ډېرو نه د يروشلم محاصره وکړئ. دې ښار ته دې سزا ورکړے شى، ځکه چې په دې کښې د ظلم او زياتى نه بغېر نور څۀ په نظر نۀ راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_6.mp3', '', 1761754199, 1761754199),
(38994, 'Jeremiah 6:7', 'Jeremiah', 6, 7, 'لکه څنګه چې د يو کوهى نه تازه اوبۀ راوځى، دغه شان د دې ښار نه تازه تازه فساد او شرارت راوځى. د دې ښار په هرې خوا او ګوټونو او کوڅو کښې د ظلم او زياتى آوازونه اورېدلے کيږى. د دې ښار بيمارى او زخمونه هر وخت زما د سترګو د وړاندې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_7.mp3', '', 1761754199, 1761754199),
(38995, 'Jeremiah 6:8', 'Jeremiah', 6, 8, 'اے د يروشلم خلقو د دې خبردارى نه سبق حاصل کړئ، کۀ زۀ تاسو نه لاس په سر شم، نو ستاسو ښار به تباه کړم، او هغه به نور د اوسېدو قابل نۀ وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_8.mp3', '', 1761754199, 1761754199),
(38996, 'Jeremiah 6:9', 'Jeremiah', 6, 9, 'مالِک خُدائ ربُ الافواج فرمائى، ”تر دې چې کوم کسان په اِسرائيل کښې پاتې شوى دى هغوئ به دوباره راوشوکولے شى، لکه څنګه چې باغوان دوباره په بوټى کښې د پاتې شوو انګورو دانو د راشوکولو لټون کوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_9.mp3', '', 1761754199, 1761754199),
(38997, 'Jeremiah 6:10', 'Jeremiah', 6, 10, 'ما ورته ووئيل، ”چا سره زۀ خبرې وکړم، چا ته خبردارے ورکړم؟ څوک به ما ته غوږ ونيسى؟ هغوئ خپل غوږونه کاڼۀ کړى دى او هغوئ اورېدل نۀ غواړى. دوئ د مالِک خُدائ کلام پورې خندا کوى. او په هغې خوشحاليږى نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_10.mp3', '', 1761754199, 1761754199),
(38998, 'Jeremiah 6:11', 'Jeremiah', 6, 11, 'نو د دې دپاره زۀ د مالِک خُدائ د قهر نه ډک شوے يم، او د برداشت نه بهر شوے يم.“ مالِک خُدائ ما ته وفرمائيل چې، ”زۀ خپله غصه په کوڅو کښې په ماشومانو او د زلمو په ډلو او په ښځې او خاوند او په سپين‌ږيرو او بوډاګانو نازلوم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_11.mp3', '', 1761754199, 1761754199),
(38999, 'Jeremiah 6:12', 'Jeremiah', 6, 12, 'مالِک خُدائ فرمائى چې، ”د هغوئ کورونه او زمکې سره د هغوئ د ښځو نورو ته حواله کړم، ځکه چې زۀ به خپل لاس د دې مُلک د خلقو په خلاف وراوږد کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_12.mp3', '', 1761754199, 1761754199),
(39000, 'Jeremiah 6:13', 'Jeremiah', 6, 13, 'د ماشومانو نه واخله تر بوډاګانو پورې هر يو د ناجائزه ګټې په لالچ کښې دى، د ‎پېغمبر نه واخله تر اِمام پورې ټول دوکه ماران دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_13.mp3', '', 1761754199, 1761754199),
(39001, 'Jeremiah 6:14', 'Jeremiah', 6, 14, 'هغوئ زما د خلقو د سختو زخمونو عرضى علاج کوى. او کله چې خير نۀ وى نو هغوئ وائى چې، خير دے، خير به شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_14.mp3', '', 1761754199, 1761754199),
(39002, 'Jeremiah 6:15', 'Jeremiah', 6, 15, 'آيا هغوئ په خپل دې پليت عمل شرمېدل څۀ؟ نه، هغوئ بلکل شرم نۀ لرلو، هغوئ په دې هم نۀ پوهيږى چې شرم څۀ ته وائى. دوئ به د تباه شوو په مينځ کښې حساب شى. زۀ به دوئ هم ختم کړم کله چې زۀ هغوئ ته سزا ورکوم،“ مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_15.mp3', '', 1761754199, 1761754199),
(39003, 'Jeremiah 6:16', 'Jeremiah', 6, 16, 'مالِک خُدائ داسې فرمائى چې، ”لاړ شئ او په چوکونو کښې ودرېږئ او ګورئ. د پخوانو او هغه لارو تپوس وکړئ کومې چې د خير طرف ته ځى. په دې لاره باندې تلل به تاسو ته خير درکړى. خو تاسو ووئيل، ”نه، مونږ به په دې باندې نۀ ځُو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_16.mp3', '', 1761754199, 1761754199),
(39004, 'Jeremiah 6:17', 'Jeremiah', 6, 17, 'بيا ما په تاسو باندې محافظان مقرر کړل چا چې به تاسو ته وئيل، د بيګل آواز ته غوږ ونيسئ. خو تاسو ووئيل چې، نه مونږ به ورته توجو نۀ ورکوو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_17.mp3', '', 1761754199, 1761754199),
(39005, 'Jeremiah 6:18', 'Jeremiah', 6, 18, 'نو د دې دپاره تاسو واورئ اے قومونو، او سوچ وکړئ، اے ګواهانو چې دوئ سره به څۀ کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_18.mp3', '', 1761754199, 1761754199),
(39006, 'Jeremiah 6:19', 'Jeremiah', 6, 19, 'اے د دُنيا قومونو غوږ شئ، زۀ په دې خلقو افت راولم، کوم چې د دوئ د خپلو منصوبو مېوه ده، ځکه چې دوئ زما کلام ته توجو ورنۀ کړه او زما شريعت يې رد کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_19.mp3', '', 1761754199, 1761754199),
(39007, 'Jeremiah 6:20', 'Jeremiah', 6, 20, 'نو بيا يې څۀ فائده ده چې دوئ د شيبا نه ما ته عطر راوړى دى، او يا د لرې مُلکونه نه قيمتى خوشبودارې مصالحې راوړى دى. زۀ به ستاسو سوزېدونکې نذرانې نۀ قبلوم. ستاسو په قربانو زۀ نۀ خوشحالېږم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_20.mp3', '', 1761754199, 1761754199),
(39008, 'Jeremiah 6:21', 'Jeremiah', 6, 21, 'نو ځکه مالِک خُدائ فرمائى، زۀ به د دې خلقو په لارو کښې د تيندک خوړلو کاڼے ولګوم چې دوئ پرې تيندک وخورى او راپرېوځى. ترڅو پلار او زامن او ګاونډيان او دوستان پرې په شريکه راپرېوځى او هلاک شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_21.mp3', '', 1761754199, 1761754199),
(39009, 'Jeremiah 6:22', 'Jeremiah', 6, 22, 'مالِک خُدائ فرمائى، ”د شمال د مُلک د خوا نه فوج راروان دے، او ستاسو خلاف يو لوئ او تکړه قوم د لرې نه د جنګ کولو په نيت راپاڅېدلے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_22.mp3', '', 1761754199, 1761754199),
(39010, 'Jeremiah 6:23', 'Jeremiah', 6, 23, 'هغوئ په ليندو او نېزو سره سمبال دى، هغوئ ټول ظالمان او بې‌رحمه دى. ټول جنګيالى يې په آسونو سوارۀ او په جنګى صف بندۍ کښې راروان دى او د هغوئ شور لکه د غضبناک سمندر په شان دے او په تا، صيون لورې، د حملې کولو دپاره تيار دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah6_verse_23.mp3', '', 1761754199, 1761754199);